plan:
{
  "tasks": [
    {
      "task_id": "T-1",
      "description": "创建 Types.h 公共类型定义：Point 结构体、Direction 枚举、游戏常量（棋盘尺寸、初始速度、刷新间隔）",
      "estimated_minutes": 8,
      "file_scope": [
        "Types.h"
      ],
      "acceptance_conditions": [
        {
          "id": "AC-1",
          "description": "Point 结构体包含 int x, int y 成员，并定义 operator== 用于坐标比较"
        },
        {
          "id": "AC-2",
          "description": "Direction 枚举包含 UP, DOWN, LEFT, RIGHT 四个方向值"
        },
        {
          "id": "AC-3",
          "description": "定义 BOARD_WIDTH=30, BOARD_HEIGHT=20 以及初始游戏速度 INITIAL_SPEED_MS=150"
        },
        {
          "id": "AC-4",
          "description": "Types.h 无任何外部依赖，可独立编译"
        }
      ],
      "dependencies": []
    },
    {
      "task_id": "T-2",
      "description": "实现 Snake 类：蛇身段管理、移动逻辑、生长与自碰撞检测",
      "estimated_minutes": 15,
      "file_scope": [
        "Snake.h",
        "Snake.cpp"
      ],
      "acceptance_conditions": [
        {
          "id": "AC-1",
          "description": "Snake 类使用 std::deque<Point> 存储蛇身段，头部为 front()"
        },
        {
          "id": "AC-2",
          "description": "move(Direction) 方法：按方向新增头部、若未吃食物则移除尾部；返回新头部坐标"
        },
        {
          "id": "AC-3",
          "description": "grow() 方法：标记下一帧不移除尾部，使蛇长度+1"
        },
        {
          "id": "AC-4",
          "description": "checkSelfCollision() 方法：检测头部是否与第2段及之后的身体段重叠"
        },
        {
          "id": "AC-5",
          "description": "Snake.h 仅依赖 <deque> 和 Types.h，Snake.cpp 正确 #include \"Snake.h\""
        }
      ],
      "dependencies": []
    },
    {
      "task_id": "T-3",
      "description": "实现 Input 模块：非阻塞键盘输入读取与方向解析",
      "estimated_minutes": 10,
      "file_scope": [
        "Input.h",
        "Input.cpp"
      ],
      "acceptance_conditions": [
        {
          "id": "AC-1",
          "description": "提供 pollDirection() 函数：非阻塞检查键盘输入，返回按下方向或 NO_INPUT 标记"
        },
        {
          "id": "AC-2",
          "description": "W/S/A/D 和方向键均能正确映射到 UP/DOWN/LEFT/RIGHT"
        },
        {
          "id": "AC-3",
          "description": "连续多次快速按键时，pollDirection 能缓冲读取最新有效方向"
        },
        {
          "id": "AC-4",
          "description": "Input.h 依赖 Types.h，Input.cpp 使用 _kbhit()/_getch()（conio.h）实现"
        }
      ],
      "dependencies": []
    },
    {
      "task_id": "T-4",
      "description": "实现 Board 类：棋盘边界、食物生成与碰撞检测",
      "estimated_minutes": 12,
      "file_scope": [
        "Board.h",
        "Board.cpp"
      ],
      "acceptance_conditions": [
        {
          "id": "AC-1",
          "description": "Board 类管理棋盘维度（BOARD_WIDTH×BOARD_HEIGHT），提供 isOutOfBounds(Point) 边界检测"
        },
        {
          "id": "AC-2",
          "description": "spawnFood() 在棋盘空白区域随机生成食物坐标，保证不与蛇身重叠"
        },
        {
          "id": "AC-3",
          "description": "checkFoodCollision(Point) 判断给定坐标是否与食物重合，命中后自动重新生成食物"
        },
        {
          "id": "AC-4",
          "description": "getFoodPosition() 返回当前食物坐标供渲染使用"
        },
        {
          "id": "AC-5",
          "description": "Board.h 依赖 Types.h 和 Snake.h（用于传蛇身排除列表），Board.cpp 使用 <cstdlib>/<ctime> 生成随机数"
        }
      ],
      "dependencies": []
    },
    {
      "task_id": "T-5",
      "description": "实现 Renderer 模块：控制台画面渲染（边框、蛇、食物、分数）",
      "estimated_minutes": 15,
      "file_scope": [
        "Renderer.h",
        "Renderer.cpp"
      ],
      "acceptance_conditions": [
        {
          "id": "AC-1",
          "description": "render() 函数清屏并绘制完整画面：双层边框（'#'外围）、蛇身（'O'头部、'o'身体）、食物（'*'）、分数显示"
        },
        {
          "id": "AC-2",
          "description": "使用 Windows Console API（SetConsoleCursorPosition）实现无闪烁刷新"
        },
        {
          "id": "AC-3",
          "description": "接受 Snake 和 Board 对象的 const 引用以获取渲染数据"
        },
        {
          "id": "AC-4",
          "description": "renderGameOver(score) 函数显示游戏结束画面和最终分数"
        },
        {
          "id": "AC-5",
          "description": "Renderer.h 仅依赖 Types.h、Snake.h、Board.h，不与 Input/Game 模块耦合"
        }
      ],
      "dependencies": []
    },
    {
      "task_id": "T-6",
      "description": "实现 Game 控制器：游戏主循环、状态管理、计时与速度递增",
      "estimated_minutes": 14,
      "file_scope": [
        "Game.h",
        "Game.cpp"
      ],
      "acceptance_conditions": [
        {
          "id": "AC-1",
          "description": "Game 类组合 Snake、Board、Renderer 实例，提供 run() 启动游戏主循环"
        },
        {
          "id": "AC-2",
          "description": "主循环每帧执行：输入轮询→方向更新→蛇移动→碰撞检测→食物检测→渲染→延时控制"
        },
        {
          "id": "AC-3",
          "description": "方向更新防止反向（如当前向右时不能直接向左），避免蛇原地掉头自撞"
        },
        {
          "id": "AC-4",
          "description": "碰撞检测包括边界碰撞（isOutOfBounds）和自碰撞（checkSelfCollision），任一触发则游戏结束"
        },
        {
          "id": "AC-5",
          "description": "每吃5个食物，游戏速度提升10%（刷新间隔缩短），并更新当前分数"
        }
      ],
      "dependencies": []
    },
    {
      "task_id": "T-7",
      "description": "实现 main.cpp 入口：初始化随机种子、创建 Game 实例并启动",
      "estimated_minutes": 5,
      "file_scope": [
        "main.cpp"
      ],
      "acceptance_conditions": [
        {
          "id": "AC-1",
          "description": "main.cpp 包含所有必要的头文件，调用 srand(time(nullptr)) 初始化随机种子"
        },
        {
          "id": "AC-2",
          "description": "创建 Game 对象并调用 run() 启动游戏"
        },
        {
          "id": "AC-3",
          "description": "游戏结束后程序正常退出，返回 0"
        }
      ],
      "dependencies": []
    }
  ]
}
